import java.io.BufferedReader;import java.io.InputStreamReader;import java.util.ArrayList;import java.util.StringTokenizer;public class TestClass {public static void main(String[] args) throws Exception {BufferedReader br = new BufferedReader(new InputStreamReader(System.in));String line = br.readLine();if (line == null) return;int n = Integer.parseInt(line.trim());if (n == 0) {System.out.println(0);return;}ArrayList<Integer>[] adj = new ArrayList[n + 1];for (int i = 1; i <= n; i++) adj[i] = new ArrayList<>();for (int i = 0; i < n - 1; i++) {StringTokenizer st = new StringTokenizer(br.readLine());int u = Integer.parseInt(st.nextToken());int v = Integer.parseInt(st.nextToken());adj[u].add(v);adj[v].add(u);}long[] depth = new long[n + 1];boolean[] visited = new boolean[n + 1];int[] stack = new int[n];int[] dStack = new int[n];int top = 0;stack[top] = 1;dStack[top] = 0;visited[1] = true;long totalPairs = 0;while (top >= 0) {int u = stack[top];int d = dStack[top--];totalPairs += (d + 1);for (int v : adj[u]) {if (!visited[v]) {visited[v] = true;stack[++top] = v;dStack[top] = d + 1;}}}System.out.println(totalPairs);}}